pub fn ssr_step(st: &Ssr, cmd: Option<SsrCmd>, new_duty: Option<u8>) -> Ssr {
    let s1 = match cmd {
        Some(SsrCmd::Lock) => Ssr { locked: true, pattern: 0 },
        Some(SsrCmd::Unlock) => Ssr { locked: false, pattern: st.pattern },
        None => *st,
    };
    if s1.locked {
        s1
    } else {
        match new_duty {
            Some(d) => {
                if d <= 100 { Ssr { locked: false, pattern: d } } else { s1 }
            }
            None => s1,
        }
    }
}

