pub fn duty_set(st: &Heater, m: &DutyMsg) -> (Heater, Handled, Effects) {
    if !m.utf8 {
        return (*st, Handled::Utf8, NO_EFFECTS);
    }
    if !m.parsed {
        return (*st, Handled::Invalid, NO_EFFECTS);
    }
    if m.duty > 100 {
        return (*st, Handled::Unexpected, NO_EFFECTS);
    }
    if !m.sender {
        return (*st, Handled::Invalid, NO_EFFECTS);
    }
    match m.control {
        Control::Manual => {
            // `transition_to_manual`: always possible.
            let changed = match st.ctl {
                Ctl::Manual => !m.same_manual,
                _ => true,
            };
            (
                Heater { ctl: Ctl::Manual, duty: m.duty },
                Handled::Ok,
                Effects { send: Some(m.duty), announce: changed, record_sender: changed },
            )
        }
        Control::Remote => match st.ctl {
            // A new remote announces itself.
            Ctl::Nobody | Ctl::Manual => (
                Heater { ctl: Ctl::Remote { expires: expires_after(m.now) }, duty: m.duty },
                Handled::Ok,
                Effects { send: Some(m.duty), announce: true, record_sender: true },
            ),
            Ctl::Remote { expires } => {
                if !m.same_remote {
                    (*st, Handled::Unexpected, NO_EFFECTS)
                } else if m.now >= expires {
                    // It failed to check in in time.
                    (*st, Handled::Unexpected, NO_EFFECTS)
                } else {
                    (
                        Heater { ctl: Ctl::Remote { expires: expires_after(m.now) }, duty: m.duty },
                        Handled::Ok,
                        Effects { send: Some(m.duty), announce: false, record_sender: false },
                    )
                }
            }
        },
        Control::Other => (*st, Handled::Unexpected, NO_EFFECTS),
        Control::Missing => (*st, Handled::Invalid, NO_EFFECTS),
    }
}

