    // ('remote' or 'manual') with a "control:<type>" property.
    let control_type = find_user_property(&message.properties, "control", None)
        .map(|property| property.value());

    match control_type {
        // The duty sender is exerting manual control.
        Some("manual") => {
            self.heater_state
                .lock()
                .await
                .transition_to_manual(sender_id, duty);

            self.ssrcontrol_duty_sender.send(duty);
            Ok(())
        }

        // The duty sender is a remote.
        Some("remote") => {
            let state_result = self
                .heater_state
                .lock()
                .await
                .remote_update_duty(sender_id, duty);

            // Remotes can lose control, returning an error.
            if state_result.is_err() {
                Err(EventHandlerError::UnexpectedApplicationMessage)
            } else {
                self.ssrcontrol_duty_sender.send(duty);
                Ok(())
            }
        }

        Some(_) => Err(EventHandlerError::UnexpectedApplicationMessage),
        None => Err(EventHandlerError::InvalidApplicationMessage),
    }
}

pub fn transition_to_manual(&mut self, device_id: impl Into<String>, heater_duty: u8) {
    let device_id = device_id.into();

    self.duty = heater_duty;

    let new_state = HeaterController::Manual {
        manual_id: device_id.clone(),
    };

    if self.controller != new_state {
        self.controller = new_state;

        self.buzzer_channel
            .try_send(&CONTROLLER_NOTIFICATION_PATTERN)
            .ok();

        if let Some(watch) = self.watch {
            watch.sender().send(self.controller.clone());
        }

        self.memlog.info(format!(
            "state: control set to Manual by device {device_id}"
        ));
    }
}

pub fn remote_update_duty(
    &mut self,
    device_id: impl Into<String>,
    heater_duty: u8,
) -> Result<(), StateError> {
    let device_id = device_id.into();

    match &mut self.controller {
        //
        // A new remote announced itself.
        HeaterController::None | HeaterController::Manual { .. } => {
            // Set the mode to Remote, record the remote's identifier.
            self.controller = HeaterController::Remote {
                remote_id: device_id.clone(),
                expires: Instant::now() + REMOTE_CHECKIN_INTERVAL,
            };

            // Update the recorded duty.
            self.duty = heater_duty;

            // Sound the buzzer.
            self.buzzer_channel
                .try_send(&CONTROLLER_NOTIFICATION_PATTERN)
                .ok();

            // Notify the state change.
            if let Some(watch) = self.watch {
                watch.sender().send(self.controller.clone());
            }

            self.memlog.info(format!(
                "state: control set to Remote by device {device_id}"
            ));

            Ok(())
        }

        //
        // Remote update while in remote control state.
        HeaterController::Remote {
            remote_id: current_remote,
            expires,
        } => {
            // See if the requesting remote is the one controlling the heater.
            if *current_remote != device_id {
                return Err(StateError::RemoteMismatch);
            }

            // See if the expiry time has elapsed.
            // We use checked_duration_since because if `expires` is in the future, a regular duration
            // calculation would underflow since Duration is unsigned.
            if Instant::now().checked_duration_since(*expires).is_some() {
                return Err(StateError::RemoteExpired);
            }

            // Update the recorded duty.
            self.duty = heater_duty;

            // Set a new expiry time.
            *expires = Instant::now() + REMOTE_CHECKIN_INTERVAL;

            Ok(())
        }
    }
}

