pub fn expire(st: &Heater, now: u64) -> (Heater, Option<u8>) {
    match st.ctl {
        Ctl::Remote { expires } => {
            if now >= expires {
                (Heater { ctl: Ctl::Nobody, duty: st.duty }, Some(0))
            } else {
                (*st, None)
            }
        }
        _ => (*st, None),
    }
}

