pub async fn expire_remote(
    ssrcontrol_duty_sender: SsrDutyDynSender,
    memlog: memlog::SharedLogger,
    state: SharedState,
) {
    loop {
        Timer::after(REMOTE_EXPIRE_POLL_INTERVAL).await;

        let mut state = state.lock().await;
        if let HeaterController::Remote { remote_id, expires } = &state.controller {
            let remote_id = remote_id.clone();

            if Instant::now().checked_duration_since(*expires).is_some() {
                ssrcontrol_duty_sender.send(0);
                state.clear_control();
                memlog.warn(format!("remote {remote_id} expired, duty set to 0"));
            }
        }
    }
}

pub fn clear_control(&mut self) {
    if self.controller != HeaterController::None {
        self.controller = HeaterController::None;

        if let Some(watch) = self.watch {
            watch.sender().send(self.controller.clone());
        }

        self.memlog.info("state: control set to None");
    }
}
